// The extension's module body. <grid/Modules.hpp> is generated by
// apiary_aggregate_extension(); APIARY_EXTENSION_MODULE is the configured
// backend's module macro, so this file is the same under pybind11 and nanobind.
#include <grid/Modules.hpp>

APIARY_EXTENSION_MODULE(_core, m) {
    m.doc() = "Apiary protocols example";
    grid_register_all(m);
}
